import type { Question } from '../questions';

export const UPSC_ESE_2026_CIVIL_PRELIMS_PAPER_2_CIVIL_ENGINEERING_1: Question[] = [
  { id: 'b14-001-ce-q001', section: 'Civil Engineering Paper II', topic: 'Building Materials', difficulty: 'easy', question: 'A concrete mix contains 180 kg of water and 360 kg of cement per cubic metre. The water-cement ratio by mass is:', options: ['0.50', '0.40', '0.60', '2.00'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The water-cement ratio is 180/360=0.50.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q002', section: 'Civil Engineering Paper II', topic: 'Building Materials — Aggregate Grading', difficulty: 'medium', question: 'For a fine aggregate, the cumulative percentages retained on six standard sieves are 5, 20, 45, 70, 90 and 98. Ignoring the pan, its fineness modulus is closest to:', options: ['3.28', '2.28', '4.28', '5.47'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Fineness modulus is the sum of cumulative percentages retained divided by 100. The sum is 328, so FM = 3.28.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q003', section: 'Civil Engineering Paper II', topic: 'Building Materials — Brick Durability', difficulty: 'medium', question: 'A brick masonry wall repeatedly becomes wet and then develops a white crystalline deposit as it dries. Which mechanism best explains the deposit?', options: ['Dissolved salts move with pore water to the surface and crystallize as the water evaporates', 'Clay minerals in the brick oxidize directly into a white powder', 'Cement hydrates are converted into gypsum only by sunlight', 'Sand grains migrate through mortar joints under capillary suction'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Efflorescence forms when soluble salts are transported by moisture and are left behind as crystals at the surface after evaporation.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q004', section: 'Civil Engineering Paper II', topic: 'Building Materials — Cement Soundness', difficulty: 'hard', question: 'Two cement pastes have similar setting times. After the standard soundness test, Paste X shows negligible delayed expansion while Paste Y expands markedly. The most defensible interpretation is:', options: ['Paste Y may contain constituents such as free lime or magnesia that hydrate slowly and cause unsound expansion', 'Paste X must have a higher water-cement ratio than Paste Y', 'Paste Y necessarily has a lower fineness than Paste X', 'Paste X must contain more gypsum than permitted because it did not expand'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Soundness concerns delayed volumetric stability after setting. Excess free CaO or MgO can hydrate later and produce harmful expansion.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q005', section: 'Civil Engineering Paper II', topic: 'Building Materials — Moisture Correction in Sand', difficulty: 'medium', question: 'A batching box is calibrated to deliver 0.60 m³ of dry sand. The sand at site shows 20% bulking by volume. What loose moist-sand volume should be measured to supply approximately the same quantity of sand solids?', options: ['0.72 m³', '0.48 m³', '0.60 m³', '0.80 m³'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Bulking of 20% means the moist apparent volume is 1.20 times the dry volume. Required box volume = 0.60×1.20 = 0.72 m³.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q006', section: 'Civil Engineering Paper II', topic: 'Building Materials', difficulty: 'medium', question: 'A 500 mL dry sand sample occupies 600 mL after slight moistening. The bulking of the sand is:', options: ['20%', '10%', '16.7%', '25%'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Bulking=(600-500)/500×100=20%.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q007', section: 'Civil Engineering Paper II', topic: 'Building Materials — Air-Entrained Concrete', difficulty: 'medium', question: 'A pavement concrete mix is modified by deliberately entraining a small, stable system of microscopic air bubbles while keeping other proportions comparable. Which performance change is most characteristic?', options: ['Higher density and a complete elimination of drying shrinkage', 'Lower workability but a large increase in elastic modulus', 'No change in durability because the bubbles disappear after hardening', 'Improved freeze-thaw durability and workability, with some possible reduction in compressive strength'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Entrained air provides pressure-relief spaces during freezing and improves workability. Excess air generally lowers density and can reduce compressive strength.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q008', section: 'Civil Engineering Paper II', topic: 'Building Materials — Water-Cement Ratio and Strength', difficulty: 'medium', question: 'Two fully compacted concretes use the same cement and aggregate and are cured identically. Mix A has a water-cement ratio of 0.44 and Mix B has 0.62. If neither suffers from inadequate workability, which outcome is most likely at 28 days?', options: ['Mix A has the higher compressive strength because its capillary porosity after hydration is generally lower', 'Mix B has the higher strength because extra water always increases hydration products', 'Both must have identical strength because cement content is unchanged', 'Strength cannot differ unless aggregate size also differs'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For comparable materials, compaction and curing, increasing water-cement ratio generally increases capillary porosity and lowers compressive strength.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q009', section: 'Civil Engineering Paper II', topic: 'Building Materials — Timber Moisture Content', difficulty: 'medium', question: 'A timber specimen weighs 12.0 kg before oven drying and 10.0 kg after reaching constant dry mass. Its moisture content on the oven-dry basis is:', options: ['20%', '16.7%', '2%', '120%'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Moisture content = (wet mass − dry mass)/dry mass ×100 = (12−10)/10×100 = 20%.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q010', section: 'Civil Engineering Paper II', topic: 'Building Materials — Cement Fineness', difficulty: 'medium', question: 'Compared with a coarser cement of the same composition, a much finer cement is generally expected to show which combination, all else equal?', options: ['Slower early strength gain and lower water demand in every mix', 'No change in hydration rate because chemistry alone controls reaction', 'Faster early hydration and greater early heat release', 'Lower specific surface and slower dissolution'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Greater specific surface exposes more cement to water, accelerating early hydration and heat evolution. It may also increase water demand.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q011', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'medium', question: 'A 4 m simply supported beam carries a single 20 kN load exactly at midspan. By symmetry, the vertical reaction at each support is:', options: ['5 kN', '10 kN', '20 kN', '40 kN'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Vertical equilibrium and symmetry share the 20 kN load equally, so each support reaction is 10 kN.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q012', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Influence Lines', difficulty: 'medium', question: 'For a 12 m simply supported beam, consider the influence line for bending moment at a section 4 m from the left support. What is the maximum ordinate of this influence line?', options: ['1.33 m', '2.00 m', '4.00 m', '2.67 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a simply supported beam, the moment influence line at a section a from the left and b from the right reaches its maximum under the section, with ordinate ab/L. Here 4×8/12=2.67 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q013', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Conjugate Beam Method', difficulty: 'medium', question: 'In the conjugate-beam method, a real beam is a cantilever fixed at A and free at B. What support condition is used for its conjugate beam?', options: ['Both A and B are simply supported', 'A is fixed and B is free', 'A is free and B is fixed', 'Both A and B are fixed'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Support transformations are chosen so that conjugate shear represents slope and conjugate moment represents deflection. A real fixed end becomes free and a real free end becomes fixed.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q014', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Moment Distribution', difficulty: 'medium', question: 'For a prismatic member AB with end B fixed, a clockwise moment of 24 kN·m is applied at A while joint translation is prevented. The carry-over moment to B has magnitude:', options: ['12 kN·m', '6 kN·m', '24 kN·m', '48 kN·m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a prismatic member with the far end fixed, the carry-over factor is 1/2. The carried-over moment therefore has magnitude 12 kN·m and the same rotational sense in the usual sign convention.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q015', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Reciprocal Theorem', difficulty: 'medium', question: 'In a linear elastic frame, a unit vertical load at joint B produces 2.8 mm vertical displacement at joint A. Under the same support conditions, a unit vertical load at A produces what vertical displacement at B?', options: ['1.4 mm', '2.8 mm', '5.6 mm', '0 mm'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Maxwell-Betti reciprocity gives the cross-flexibility coefficients f_AB=f_BA for a linear elastic structure.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q016', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'medium', question: 'A planar truss has 8 joints, 13 members and 3 external reaction components. Using m+r-2j, its degree of static indeterminacy is:', options: ['1', '2', '0', '3'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: '13+3-2×8=0, so the idealised truss is statically determinate.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q017', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Sidesway Frames', difficulty: 'medium', question: 'A one-bay portal frame has equal column heights but substantially different column flexural stiffnesses. It carries only symmetric vertical beam loading. Which statement about a slope-deflection analysis is safest?', options: ['Sidesway is impossible whenever the external load is vertical', 'Sidesway occurs only if both column bases are hinges', 'Sidesway can occur because the unequal column stiffnesses make the frame response unsymmetric', 'Sidesway is prevented solely because the beam loading is symmetric'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'A nominally symmetric load does not guarantee zero lateral translation when the frame stiffness or geometry is unsymmetric.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q018', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Unit-Load Method', difficulty: 'medium', question: 'To calculate a vertical deflection at a point of a linearly elastic beam when bending deformation dominates, the unit-load method uses which integral?', options: ['∫(M m / EI) dx', '∫(M² / EI) dx only', '∫(V v / EA) dx', '∫(N n / GJ) dx'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'M is the bending moment from the real loading and m is the bending moment produced by a unit load applied at the point and in the direction of the required displacement.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q019', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Plastic Analysis', difficulty: 'medium', question: 'A rectangular steel section first yields in bending at 80 kN·m. Neglecting local buckling, its fully plastic moment is approximately:', options: ['80 kN·m', '120 kN·m', '100 kN·m', '160 kN·m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The shape factor of a rectangular section is 1.5, so M_p=1.5M_y=1.5×80=120 kN·m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q020', section: 'Civil Engineering Paper II', topic: 'Structural Analysis — Joint Distribution Factors', difficulty: 'medium', question: 'At a rigid joint, two prismatic members have near-end rotational stiffnesses 4EI/L and 3EI/L, with their far ends fixed. The moment-distribution factor for the first member is:', options: ['4/7', '3/7', '1/4', '7/4'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'A distribution factor equals member stiffness divided by the sum of stiffnesses meeting at the joint: 4/(4+3)=4/7.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q021', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'easy', question: 'At a point in saturated soil, total vertical stress is 180 kPa and pore-water pressure is 65 kPa. The effective vertical stress is:', options: ['65 kPa', '180 kPa', '115 kPa', '245 kPa'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Effective stress equals total stress minus pore pressure: 180-65=115 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q022', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Seepage and Effective Stress', difficulty: 'hard', question: 'A 2 m thick saturated sand layer has submerged unit weight 10 kN/m³. Upward seepage occurs with hydraulic gradient 0.60. Ignoring side effects, the effective vertical stress at the bottom of the layer is closest to:', options: ['20 kPa', '12 kPa', '8 kPa', '32 kPa'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Without seepage the effective overburden is γ′z=10×2=20 kPa. Upward seepage reduces it by iγ_w z≈0.60×10×2=12 kPa, leaving about 8 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q023', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Consolidation', difficulty: 'medium', question: 'Two clay layers have the same coefficient of consolidation and boundary drainage condition. If the drainage path of Layer B is twice that of Layer A, the time needed to reach the same degree of consolidation in B is:', options: ['Twice that for A', 'Half that for A', 'Eight times that for A', 'Four times that for A'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For one-dimensional consolidation, T_v=c_v t/H_d². At the same T_v and c_v, time is proportional to the square of the drainage path.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q024', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Relative Density', difficulty: 'medium', question: 'For a sand, e_max=0.90, e_min=0.50 and the in-situ void ratio is 0.60. The relative density is:', options: ['75%', '25%', '40%', '60%'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'D_r=(e_max−e)/(e_max−e_min)=(0.90−0.60)/(0.90−0.50)=0.30/0.40=0.75.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q025', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Earth Pressure', difficulty: 'medium', question: 'A smooth vertical retaining wall supports dry cohesionless backfill with φ=30° and a horizontal surface. Under Rankine active conditions, the coefficient K_a is:', options: ['1/3', '1/2', '2/3', '3'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'K_a=(1−sinφ)/(1+sinφ). With sin30°=0.5, K_a=0.5/1.5=1/3.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q026', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'hard', question: 'A saturated sand has specific gravity 2.65 and void ratio 0.65. Taking water unit weight as 9.81 kN/m³, its critical hydraulic gradient is closest to:', options: ['0.61', '1.65', '2.65', '1.00'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'ic=(Gs-1)/(1+e)=1.65/1.65=1.00.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q027', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Clay Sensitivity', difficulty: 'medium', question: 'An undisturbed clay has undrained shear strength 60 kPa. After complete remoulding at the same water content, its strength is 15 kPa. Its sensitivity is:', options: ['0.25', '45', '4', '75'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Sensitivity is the ratio of undisturbed to remoulded strength: 60/15=4.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q028', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Dilatancy of Sand', difficulty: 'hard', question: 'During drained shearing, a dense sand specimen shows net volume expansion after a small initial contraction. Which consequence is most consistent with this behavior?', options: ['Its pore-water pressure must remain permanently positive even in a drained test', 'Its friction angle at peak must be smaller than the critical-state angle', 'The specimen must be a normally consolidated clay rather than sand', 'Its peak shear strength can exceed its critical-state strength because dilation contributes to resistance'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Dense granular soils dilate during shear. The work required for dilation contributes to peak resistance, so the peak friction angle can exceed the critical-state value.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q029', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Pile Dragload', difficulty: 'medium', question: 'A pile passes through a recently placed compressible fill into firm soil. As the fill consolidates, the soil settles more than the pile over the upper length. What is the principal effect on the pile above the neutral plane?', options: ['Upward shaft resistance reduces the pile load to zero', 'Only horizontal bending develops; axial load is unaffected', 'The pile experiences tensile uplift from the settling soil', 'Downward negative skin friction adds compressive dragload to the pile'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Where surrounding soil moves downward relative to the pile, shaft shear acts downward on the pile. This negative skin friction increases axial compressive load down to the neutral plane.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q030', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Flow Nets', difficulty: 'medium', question: 'A flownet for seepage beneath a structure has total head loss 9 m and 6 equipotential drops. The head loss between adjacent equipotential lines is:', options: ['0.67 m', '3 m', '1.5 m', '54 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Each potential drop represents Δh=H/N_d=9/6=1.5 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q031', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'easy', question: 'A wastewater sample has dissolved oxygen 8.5 mg/L initially and 3.5 mg/L after the specified BOD incubation, with no dilution correction needed. The BOD indicated is:', options: ['3.5 mg/L', '5.0 mg/L', '8.5 mg/L', '12.0 mg/L'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'BOD is the oxygen depletion: 8.5-3.5=5.0 mg/L under the stated simplified conditions.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q032', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Chlorination', difficulty: 'medium', question: 'During stepwise chlorination of water containing ammonia and other reducing substances, the measured residual first falls after formation of chloramines and then begins to rise as free chlorine. The dose at this turning region corresponds to:', options: ['Prechlorination only', 'Superchlorination followed by dechlorination', 'Breakpoint chlorination', 'Plain sedimentation'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'At the breakpoint, chlorine demand and chloramine reactions have essentially been satisfied; additional chlorine produces a free residual.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q033', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Coagulation', difficulty: 'medium', question: 'A raw water contains stable negatively charged colloids that pass through plain sedimentation. Adding alum at an appropriate pH mainly helps because it:', options: ['Sterilizes the water by releasing free chlorine', 'Destabilizes the colloids so collisions can produce settleable flocs', 'Increases colloid surface charge so particles repel more strongly', 'Removes dissolved salts only by evaporation'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Coagulation reduces electrostatic stability, allowing flocculation to form larger aggregates that can settle or be filtered.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q034', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Activated Sludge', difficulty: 'hard', question: 'In an activated-sludge test, 1 L of mixed liquor containing 3,000 mg/L of suspended solids settles to 240 mL after 30 minutes. The sludge volume index is:', options: ['8 mL/g', '80 mL/g', '240 mL/g', '720 mL/g'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'SVI = settled sludge volume (mL/L) divided by MLSS (g/L) = 240/3 = 80 mL/g.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q035', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Lake Eutrophication', difficulty: 'medium', question: 'A lake receiving phosphorus-rich runoff develops dense algal blooms, large day-night oxygen swings and occasional fish kills. Which intervention addresses the root cause most directly?', options: ['Increase the colour of the water to reduce visibility', 'Add more biodegradable organic matter', 'Reduce external nutrient loading to the lake', 'Deepen only the boat-navigation channel'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Eutrophication is driven by excessive nutrient supply, commonly phosphorus or nitrogen. Source control reduces the productivity that causes oxygen problems.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q036', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'A water-treatment plant applies 4.0 mg/L chlorine and measures a residual of 0.8 mg/L after the specified contact period. The chlorine demand is:', options: ['0.8 mg/L', '3.2 mg/L', '4.8 mg/L', '5.0 mg/L'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Chlorine demand equals dose minus residual: 4.0-0.8=3.2 mg/L.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q037', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Water Hardness', difficulty: 'medium', question: 'A groundwater sample contains high concentrations of Ca²⁺ and Mg²⁺ but little suspended matter. Which treatment objective is most directly indicated if scale formation in boilers is the concern?', options: ['Hardness removal or softening', 'Coagulation for turbidity removal', 'Aeration solely for dissolved oxygen addition', 'Screening of coarse solids'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Calcium and magnesium ions are the principal contributors to hardness and scale; softening targets these dissolved multivalent cations.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q038', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Disinfection', difficulty: 'medium', question: 'A treatment plant has already removed most suspended solids and now needs a barrier specifically against disease-causing microorganisms before distribution. Which process is the relevant final barrier?', options: ['Disinfection', 'Rapid mixing', 'Sedimentation', 'Flocculation'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Disinfection is intended to inactivate pathogenic microorganisms. The other listed operations mainly remove particles rather than provide the microbiological barrier.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q039', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'In an aerated biological treatment stage, ammonium concentration falls while nitrite and nitrate concentrations rise. Which process most directly explains the conversion?', options: ['eutrophication', 'trickling filter', 'jar test', 'nitrification'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Under aerobic conditions, nitrifying microorganisms oxidize ammonium first to nitrite and then to nitrate; this conversion is nitrification.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q040', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering — Jar Testing', difficulty: 'medium', question: 'Six beakers of the same raw water receive different alum doses, are rapidly mixed, gently flocculated and allowed to settle. The operator compares residual turbidity. The experiment is being used primarily to:', options: ['Measure biochemical oxygen demand directly', 'Determine pipe friction factor', 'Calibrate a chlorine contact tank volume', 'Select a practical coagulant dose and mixing condition for that water'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'A jar test simulates coagulation-flocculation at bench scale so treatment conditions can be selected for the current raw water.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q041', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'easy', question: 'At a signalized approach, the cycle length is 90 s and the effective green available to the movement is 36 s. The effective green ratio g/C is:', options: ['0.25', '0.40', '0.60', '2.50'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The effective green ratio is 36/90=0.40.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q042', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Traffic Flow Equivalency', difficulty: 'medium', question: 'In one hour a lane carries 400 cars, 100 buses and 200 two-wheelers. If their adopted PCU factors are 1.0, 3.0 and 0.5 respectively, the flow is:', options: ['600 PCU/h', '700 PCU/h', '1,100 PCU/h', '800 PCU/h'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Equivalent flow = 400×1 + 100×3 + 200×0.5 = 400+300+100 = 800 PCU/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q043', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Flexible Pavement Subgrade', difficulty: 'medium', question: 'Two otherwise similar flexible-pavement sites have soaked subgrade CBR values of 3% and 8%. For the same design traffic, the site with CBR 8% generally requires:', options: ['A larger thickness because higher CBR means weaker soil', 'Exactly the same thickness because CBR is unrelated to pavement support', 'A smaller structural thickness because the subgrade is stronger', 'No pavement layer above the subgrade'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Higher CBR indicates greater penetration resistance and subgrade support. Standard flexible-pavement designs therefore generally reduce required crust thickness as CBR rises, all else equal.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q044', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Transition Curves', difficulty: 'hard', question: 'A vehicle enters a circular curve of radius 400 m at 20 m/s through a transition. If the allowable rate of change of radial acceleration is 0.5 m/s³, the transition length based on this criterion is:', options: ['40 m', '20 m', '80 m', '160 m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For constant-speed transition design, rate of change of radial acceleration C=v³/(RL). Thus L=v³/(CR)=20³/(0.5×400)=40 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q045', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Stopping Sight Distance', difficulty: 'medium', question: 'A car travels at 72 km/h on a level road. Taking perception-reaction time as 2.5 s and constant braking deceleration as 4 m/s², the stopping sight distance is closest to:', options: ['50 m', '75 m', '100 m', '150 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Speed is 20 m/s. Reaction distance=20×2.5=50 m; braking distance=v²/(2a)=400/8=50 m. Total=100 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q046', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'medium', question: 'A road has a 7.0 m carriageway and 2.5% camber from crown to each edge. The crown is above either edge by:', options: ['43.75 mm', '87.5 mm', '175 mm', '250 mm'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Half-width is 3.5 m; rise=0.025×3.5=0.0875 m=87.5 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q047', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Axle Load Equivalency', difficulty: 'medium', question: 'Under the fourth-power approximation for flexible-pavement damage, an axle carrying twice the standard axle load causes approximately how many times the damage of one standard axle?', options: ['2 times', '4 times', '8 times', '16 times'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Relative damage is approximately proportional to the fourth power of axle-load ratio: 2⁴=16.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q048', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Signal Timing', difficulty: 'hard', question: 'For an isolated signal, the total lost time per cycle is 12 s and the sum of critical flow ratios is 0.75. Using Webster’s optimum-cycle approximation C₀=(1.5L+5)/(1−Y), C₀ is:', options: ['69 s', '48 s', '108 s', '92 s'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'C₀=(1.5×12+5)/(1−0.75)=(18+5)/0.25=23/0.25=92 s.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q049', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Superelevation', difficulty: 'medium', question: 'A horizontal curve has radius 300 m and design speed 80 km/h. If side-friction factor 0.15 is used with e+f=v²/(127R), the required superelevation e is closest to:', options: ['0.168', '0.018', '0.150', '0.318'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'v²/(127R)=6400/(127×300)=0.168. Hence e≈0.168−0.150=0.018.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q050', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Speed Measures', difficulty: 'medium', question: 'Two vehicles each traverse the same 1 km road segment, one at 40 km/h and the other at 60 km/h. The space-mean speed of the two observations is:', options: ['50 km/h', '45 km/h', '52 km/h', '48 km/h'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For equal distances, space-mean speed is the harmonic mean: 2/(1/40+1/60)=48 km/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q051', section: 'Civil Engineering Paper II', topic: 'Surveying', difficulty: 'medium', question: 'A benchmark has RL 100.000 m. A backsight of 1.455 m and a foresight of 0.865 m are taken from one setup. The RL of the foresight point is:', options: ['99.410 m', '100.865 m', '100.590 m', '101.455 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'RL=100.000+1.455-0.865=100.590 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q052', section: 'Civil Engineering Paper II', topic: 'Surveying — Tacheometry', difficulty: 'medium', question: 'With a tacheometer on a horizontal line of sight, the staff intercept is 1.20 m. If the multiplying constant is 100 and the additive constant is negligible, the horizontal distance is:', options: ['120 m', '12 m', '100 m', '1,200 m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For horizontal sight D=Ks+C. With K=100, s=1.20 m and C≈0, D=120 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q053', section: 'Civil Engineering Paper II', topic: 'Surveying — Differential Levelling', difficulty: 'medium', question: 'A backsight of 1.455 m is taken on a benchmark of RL 100.000 m. A foresight to point P from the same instrument setup is 2.105 m. The RL of P is:', options: ['98.545 m', '100.650 m', '103.560 m', '99.350 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Height of instrument =100.000+1.455=101.455 m. RL(P)=101.455−2.105=99.350 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q054', section: 'Civil Engineering Paper II', topic: 'Surveying — Curvature and Refraction', difficulty: 'hard', question: 'Using the usual combined curvature-and-refraction correction C≈−0.0673d² metres for sight length d in kilometres, the correction for a 2 km sight is closest to:', options: ['−0.067 m', '+0.269 m', '−1.346 m', '−0.269 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'C=−0.0673×2²=−0.2692 m, approximately −0.269 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q055', section: 'Civil Engineering Paper II', topic: 'Surveying — Traverse Computation', difficulty: 'medium', question: 'A traverse line is 100 m long and has whole-circle bearing 30°. Taking northing as latitude and easting as departure, its latitude and departure are approximately:', options: ['+50.0 m, +86.6 m', '+86.6 m, +50.0 m', '−86.6 m, +50.0 m', '+86.6 m, −50.0 m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Latitude=L cosθ=100cos30°=86.6 m north; departure=L sinθ=100sin30°=50.0 m east.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q056', section: 'Civil Engineering Paper II', topic: 'Surveying', difficulty: 'medium', question: 'A whole-circle bearing of 218° is expressed in reduced-bearing form as:', options: ['N 38° W', 'S 52° W', 'S 38° W', 'N 52° E'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: '218° lies in the southwest quadrant and is 38° west of south.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q057', section: 'Civil Engineering Paper II', topic: 'Surveying — Plane-Table Orientation', difficulty: 'medium', question: 'After moving a plane table from station A to station B, the surveyor rotates the board until the plotted line ba sights back exactly to ground station A. This operation primarily establishes:', options: ['Orientation of the table at B', 'The scale of the map', 'The contour interval', 'The magnetic declination'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Backsighting aligns the plotted and ground directions of a known line, thereby orienting the plane table at the new station.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q058', section: 'Civil Engineering Paper II', topic: 'Surveying — Slope Distance Reduction', difficulty: 'medium', question: 'An EDM measures a slope distance of 250.0 m to a target at a vertical angle of 6° above the horizontal. The corresponding horizontal distance is closest to:', options: ['247.0 m', '250.0 m', '265.5 m', '248.6 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Horizontal distance =250 cos6°≈250×0.99452=248.6 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q059', section: 'Civil Engineering Paper II', topic: 'Surveying — Contour Interpolation', difficulty: 'medium', question: 'Along a straight 40 m line between points of RL 102 m and 110 m, ground slope is assumed uniform. The 106 m contour crosses the line at what distance from the 102 m point?', options: ['10 m', '16 m', '20 m', '30 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: '106 m is 4 m above 102 m out of the total 8 m rise, so the fraction is 4/8=1/2. Half of 40 m is 20 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q060', section: 'Civil Engineering Paper II', topic: 'Surveying — Coordinate Area', difficulty: 'medium', question: 'A triangular plot has coordinate vertices (0,0), (4,0) and (0,3), in metres. Its area from coordinates is:', options: ['6 m²', '7 m²', '12 m²', '3 m²'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The triangle is right-angled with base 4 m and height 3 m, so area=1/2×4×3=6 m².', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q061', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'hard', question: 'A simply supported beam of span 6 m carries a 48 kN point load at midspan. What is the maximum bending moment?', options: ['72.0 kN·m', '57.6 kN·m', '86.4 kN·m', '108.0 kN·m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a central point load on a simply supported beam, Mmax=PL/4=48×6/4=72 kN·m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q062', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'hard', question: 'A fixed-ended prismatic beam 5 m long carries a UDL of 24 kN/m over the whole span. What is the magnitude of either fixed-end moment?', options: ['40.0 kN·m', '60.0 kN·m', '75.0 kN·m', '50.0 kN·m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a full-span UDL on a fixed-fixed beam, |Mend|=wL²/12=24×25/12=50 kN·m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q063', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'hard', question: 'A cantilever 3 m long carries a 20 kN tip load. If EI=60,000 kN·m², what is the tip deflection?', options: ['2.4 mm', '3.6 mm', '4.5 mm', '3.0 mm'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'δ=PL³/(3EI)=20×27/(3×60000)=0.003 m=3 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q064', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'hard', question: 'A symmetric three-hinged parabolic arch has span 20 m and rise 4 m. A 60 kN load acts at the crown. What horizontal thrust develops?', options: ['60.0 kN', '75.0 kN', '90.0 kN', '112.5 kN'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a crown point load on this symmetric three-hinged arch, H=PL/(4h)=60×20/(16)=75 kN.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q065', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'medium', question: 'A propped cantilever beam in a plane has how many degrees of external static indeterminacy?', options: ['0', '2', '1', '3'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The fixed support supplies three reaction components and the prop one; three planar equilibrium equations leave one redundant reaction.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q066', section: 'Civil Engineering Paper II', topic: 'Structural Analysis', difficulty: 'medium', question: 'For an 8 m simply supported beam, a unit load is 3 m from the left support. What is the ordinate of the influence line for the left reaction at that load position?', options: ['0.375', '0.500', '0.625', '0.750'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The left-reaction influence-line ordinate is (L−x)/L=(8−3)/8=0.625.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q067', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'medium', question: 'A 100 kN axial load elongates a 2 m steel bar of area 500 mm². Take E=200 GPa. Find the elongation.', options: ['1.6 mm', '2.0 mm', '2.4 mm', '3.0 mm'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'δ=PL/(AE)=100000×2000/(500×200000)=2 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q068', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'hard', question: 'A steel member is fully restrained against thermal expansion. For E=200 GPa, α=12×10⁻⁶/°C and a temperature rise of 40°C, what compressive thermal stress develops?', options: ['76.8 MPa', '115.2 MPa', '144.0 MPa', '96.0 MPa'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'σ=EαΔT=200000×12×10⁻⁶×40=96 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q069', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'hard', question: 'A solid circular shaft 80 mm in diameter transmits 4 kN·m torque. What is the maximum torsional shear stress?', options: ['31.83 MPa', '47.75 MPa', '39.79 MPa', '59.69 MPa'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a solid shaft, τmax=16T/(πd³)=39.79 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q070', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'hard', question: 'At a point, σx=80 MPa, σy=20 MPa and τxy=30 MPa. What is the major principal stress?', options: ['73.94 MPa', '110.92 MPa', '92.43 MPa', '138.65 MPa'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'σ1=(σx+σy)/2+sqrt[((σx−σy)/2)²+τ²]=50+sqrt(30²+30²)=92.43 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q071', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'hard', question: 'A 50 kN tensile force acts on a 2 m prismatic bar of area 1000 mm² and E=200 GPa. What strain energy is stored?', options: ['10.0 J', '12.5 J', '15.0 J', '18.8 J'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'U=P²L/(2AE)=12.5 J after consistent SI-unit substitution.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q072', section: 'Civil Engineering Paper II', topic: 'Solid Mechanics', difficulty: 'hard', question: 'A pin-ended column has E=200 GPa, I=8×10⁻⁶ m⁴ and length 4 m. What is its Euler critical load?', options: ['789.57 kN', '1184.35 kN', '986.96 kN', '1480.44 kN'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Pcr=π²EI/L²=986.96 kN.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q073', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'Water with kinematic viscosity 1.0×10⁻⁶ m²/s flows at 0.020 m/s in a 0.10 m pipe. The Reynolds number is:', options: ['200', '2000', '20000', '5000'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Re=VD/ν=0.020×0.10/10⁻⁶=2000.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q074', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'In steady incompressible flow, a 0.30 m diameter pipe contracts to 0.15 m. If upstream velocity is 2 m/s, what is downstream velocity?', options: ['6.4 m/s', '9.6 m/s', '8.0 m/s', '12.0 m/s'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Continuity gives A1V1=A2V2. Halving diameter quarters area, so velocity becomes four times larger: 8 m/s.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q075', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'hard', question: 'Water flows horizontally without loss. At section 1, pressure is 200 kPa and velocity 2 m/s; at section 2 velocity is 6 m/s. What is the section-2 pressure?', options: ['147 kPa', '221 kPa', '276 kPa', '184 kPa'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Bernoulli at equal elevations gives p2=p1+ρ(V1²−V2²)/2=184 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q076', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'A vertical rectangular gate is 2 m wide and 3 m deep with its top at the free surface. What hydrostatic resultant acts on it?', options: ['70.63 kN', '88.29 kN', '105.95 kN', '132.44 kN'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'F=ρgAybar=9.81×(2×3)×1.5=88.29 kN.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q077', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'For the same 3 m-deep vertical rectangular surface with its top at the water surface, at what depth below the surface does the resultant hydrostatic force act?', options: ['1.6 m', '2.4 m', '3.0 m', '2.0 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a vertical rectangle starting at the free surface, ycp=2h/3=2 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q078', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'A jet of water discharges at 0.05 m³/s with speed 20 m/s and is brought to rest in the jet direction by a flat plate. Neglect losses. What force acts on the plate?', options: ['800 N', '1200 N', '1500 N', '1000 N'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Momentum change gives F=ρQV=1000×0.05×20=1000 N.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q079', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'hard', question: 'Using Darcy-Weisbach with f=0.020, find the head loss in a 300 m long, 0.30 m diameter pipe carrying water at 2 m/s.', options: ['3.26 m', '4.08 m', '4.90 m', '6.12 m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'hf=f(L/D)V²/(2g)=0.02×1000×4/19.62=4.08 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q080', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'hard', question: 'For fully developed laminar flow in the same circular pipe, if mean velocity is doubled while fluid properties remain fixed, the frictional head loss becomes:', options: ['twice as large', 'four times as large', 'half as large', 'unchanged'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'In laminar flow f=64/Re, so Darcy head loss is proportional to V rather than V² when other properties are fixed.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q081', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'Two pipes of different diameters are connected in series under steady incompressible flow with no branching. Which quantity must be the same in both pipes?', options: ['mean velocity', 'volumetric discharge', 'friction slope', 'Reynolds number'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Continuity requires the same discharge through series pipes; velocity may differ because area differs.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q082', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'A line has minor-loss coefficients totaling K=3.0 and carries water at 2 m/s. What minor head loss corresponds to those fittings?', options: ['0.61 m', '0.49 m', '0.73 m', '0.92 m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'hm=K V²/(2g)=3×4/19.62=0.612 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q083', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'medium', question: 'A pipe loses 6 m of head over 300 m length. Its hydraulic gradient is:', options: ['0.020', '0.002', '0.200', '50'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Hydraulic gradient equals head loss divided by length: 6/300=0.020.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q084', section: 'Civil Engineering Paper II', topic: 'Fluid Mechanics', difficulty: 'hard', question: 'A boundary layer has a linear velocity profile u/U=y/δ with thickness δ=20 mm. What is its displacement thickness?', options: ['8.0 mm', '12.0 mm', '10.0 mm', '15.0 mm'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'δ*=∫0^δ(1−u/U)dy=δ/2=10 mm for a linear profile.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q085', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'A soil has void ratio e=0.60. Its porosity is:', options: ['60.0%', '40.0%', '62.5%', '37.5%'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'n=e/(1+e)=0.60/1.60=0.375.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q086', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'A dry soil has Gs=2.70 and e=0.50. Using γw=9.81 kN/m³, find its dry unit weight.', options: ['17.66 kN/m³', '14.13 kN/m³', '21.19 kN/m³', '26.49 kN/m³'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'γd=Gsγw/(1+e)=2.70×9.81/1.50=17.66 kN/m³.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q087', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'hard', question: 'For a soil with w=18%, Gs=2.65 and e=0.75, the degree of saturation is closest to:', options: ['48.0%', '75.0%', '84.8%', '63.6%'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Using Se=wGs, S=0.18×2.65/0.75=0.636.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q088', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'A sand has emax=0.90, emin=0.40 and in-situ e=0.55. Its relative density is:', options: ['30%', '55%', '70%', '90%'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Dr=(emax−e)/(emax−emin)=(0.90−0.55)/0.50=0.70.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q089', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'A fine soil has liquid limit 50%, plastic limit 20% and natural water content 35%. Its liquidity index is:', options: ['0.30', '0.70', '1.50', '0.50'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'LI=(w−PL)/(LL−PL)=15/30=0.50.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q090', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'easy', question: 'A soil has liquid limit 40% and plastic limit 22%. What is its plasticity index?', options: ['18%', '62%', '11%', '28%'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'PI=LL−PL=40−22=18%.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q091', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'hard', question: 'At a site the water table is at ground level and saturated unit weight is 20 kN/m³. Taking γw=9.81 kN/m³, what is vertical effective stress 5 m below ground?', options: ['40.76 kPa', '50.95 kPa', '61.14 kPa', '76.43 kPa'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'σ\'=γ\' z=(20−9.81)×5=50.95 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q092', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'hard', question: 'For water in a clean capillary tube of diameter 0.10 mm, take surface tension 0.072 N/m, contact angle 0° and γw=9810 N/m³. Estimate capillary rise.', options: ['0.294 m', '0.235 m', '0.353 m', '0.441 m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'h=4T/(γwd)=4×0.072/(9810×0.0001)=0.294 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q093', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'hard', question: 'A normally consolidated clay layer is 3 m thick with Cc=0.30 and e0=0.80. Effective stress rises from 100 to 200 kPa. Estimate primary consolidation settlement.', options: ['0.121 m', '0.181 m', '0.226 m', '0.151 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'S=H Cc/(1+e0) log10(200/100)=0.151 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q094', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering — Eccentric Footing', difficulty: 'hard', question: 'A strip footing 2.4 m wide carries a vertical load whose resultant is eccentric by 0.30 m from the footing centreline. Using the effective-width concept for bearing capacity, the effective footing width is:', options: ['2.1 m', '2.4 m', '1.8 m', '3.0 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For one-way eccentricity, the effective width is B′=B−2e=2.4−0.60=1.8 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q095', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'An undisturbed saturated clay specimen fails in unconfined compression at 200 kPa. Its undrained shear strength is:', options: ['50 kPa', '200 kPa', '400 kPa', '100 kPa'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For saturated clay in an unconfined compression test, qu=2cu, so cu=100 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q096', section: 'Civil Engineering Paper II', topic: 'Geotechnical Engineering', difficulty: 'medium', question: 'For a cohesionless backfill with φ=30° and horizontal ground, Rankine active earth-pressure coefficient Ka equals:', options: ['1/2', '2/3', '1/3', '3'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Ka=(1−sinφ)/(1+sinφ)=(1−0.5)/(1+0.5)=1/3.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q097', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'medium', question: 'A 25 ha catchment has runoff coefficient 0.60 and design rainfall intensity 80 mm/h. Using Q=0.00278CiA, estimate peak discharge.', options: ['2.67 m³/s', '3.34 m³/s', '4.01 m³/s', '5.01 m³/s'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Q=0.00278×0.60×80×25=3.336 m³/s.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q098', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'hard', question: 'For an event with return period 2 years, what is the probability of at least one exceedance in the next 3 independent years?', options: ['12.5%', '87.5%', '50.0%', '75.0%'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Annual non-exceedance probability is 0.5; over three years it is 0.5³=0.125, so at least one exceedance is 0.875.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q099', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'medium', question: 'Three Thiessen polygons occupy 20%, 30% and 50% of a basin and receive 50, 80 and 100 mm rainfall. The areal mean rainfall is:', options: ['84 mm', '76 mm', '80 mm', '92 mm'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Weighted mean=0.2×50+0.3×80+0.5×100=84 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q100', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'hard', question: 'Hourly rainfall intensities are 20, 40, 30 and 10 mm/h. Direct runoff depth is 40 mm. Assuming a constant φ-index, its value is closest to:', options: ['10.0 mm/h', '15.0 mm/h', '16.7 mm/h', '20.0 mm/h'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Because φ exceeds 10, runoff=(20−φ)+(40−φ)+(30−φ)=90−3φ=40, giving φ=16.7 mm/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q101', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'medium', question: 'At a given time a 1-cm unit hydrograph ordinate is 12 m³/s. If 2 cm of effective rainfall occurs with the same duration and linear-response assumptions, the corresponding direct-runoff ordinate is:', options: ['6 m³/s', '12 m³/s', '24 m³/s', '36 m³/s'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Unit-hydrograph linearity scales ordinates in direct proportion to effective rainfall depth: 2×12=24 m³/s.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q102', section: 'Civil Engineering Paper II', topic: 'Hydrology', difficulty: 'hard', question: 'Over one hour, reservoir inflow rises linearly from 30 to 50 m³/s while outflow rises from 20 to 30 m³/s. Using trapezoidal averages, the storage increase is:', options: ['54,000 m³', '18,000 m³', '36,000 m³', '90,000 m³'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Average inflow is 40 and average outflow 25 m³/s; net 15 m³/s for 3600 s gives 54,000 m³.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q103', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'A sedimentation tank treats 18,000 m³/day and has 600 m² plan area. Its surface overflow rate is:', options: ['20 m³/m²·day', '60 m³/m²·day', '108 m³/m²·day', '30 m³/m²·day'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Surface overflow rate=Q/A=18000/600=30 m³/m²·day.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q104', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'hard', question: 'A wastewater has BOD5=200 mg/L. If first-order BOD exertion uses k=0.23 day⁻¹ (base e), the ultimate BOD L0 is closest to:', options: ['293 mg/L', '137 mg/L', '200 mg/L', '400 mg/L'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'BOD5=L0(1−e^(−0.23×5)); the bracket is about 0.683, so L0≈293 mg/L.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q105', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'easy', question: 'A water sample has chlorine demand 1.8 mg/L. To leave 0.5 mg/L free residual after contact, the applied chlorine dose should be:', options: ['1.3 mg/L', '1.8 mg/L', '2.3 mg/L', '3.6 mg/L'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Dose=demand+desired residual=1.8+0.5=2.3 mg/L.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q106', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'In a 30-minute settleability test, activated sludge occupies 240 mL/L and MLSS is 3000 mg/L. The sludge volume index is:', options: ['40 mL/g', '80 mL/g', '120 mL/g', '800 mL/g'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'SVI=settled volume×1000/MLSS=240×1000/3000=80 mL/g.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q107', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'A treatment basin has effective volume 4500 m³ and flow 15,000 m³/day. Its nominal hydraulic detention time is:', options: ['3.3 h', '14.4 h', '30 h', '7.2 h'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 't=V/Q=0.3 day=7.2 h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q108', section: 'Civil Engineering Paper II', topic: 'Environmental Engineering', difficulty: 'medium', question: 'Water contains 2.0 meq/L alkalinity. Expressed as CaCO3, this equals:', options: ['100 mg/L as CaCO3', '40 mg/L as CaCO3', '50 mg/L as CaCO3', '200 mg/L as CaCO3'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'One meq/L corresponds to 50 mg/L as CaCO3, so 2.0 meq/L gives 100 mg/L.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q109', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'easy', question: 'Vehicles in a lane have a mean time headway of 1.8 s. The corresponding flow is:', options: ['1800 veh/h', '2000 veh/h', '2160 veh/h', '3600 veh/h'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'q=3600/h=3600/1.8=2000 veh/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q110', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'hard', question: 'Under Greenshields\' model, free-flow speed is 80 km/h and jam density 160 veh/km. At density 40 veh/km, the flow is:', options: ['2400 veh/h', '1600 veh/h', '3200 veh/h', '4800 veh/h'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'v=80(1−40/160)=60 km/h, so q=kv=40×60=2400 veh/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q111', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'hard', question: 'For level road, estimate stopping sight distance at 72 km/h with reaction time 2.5 s and longitudinal friction coefficient 0.35. Use SSD=0.278Vt+V²/(254f).', options: ['72 m', '108 m', '90 m', '144 m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'SSD≈0.278×72×2.5+72²/(254×0.35)=108.4 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q112', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'hard', question: 'A 400 m radius highway curve is designed for 80 km/h. If lateral friction factor is 0.10, use e+f=V²/(127R). Required superelevation e is closest to:', options: ['0.026', '0.010', '0.100', '0.126'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'V²/(127R)=6400/(127×400)=0.126; e=0.126−0.10=0.026.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q113', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'medium', question: 'If pavement thickness is being selected only from subgrade support, what is the usual effect of a higher CBR value, all else equal?', options: ['a higher required pavement thickness', 'a lower required pavement thickness', 'no change in thickness', 'automatic need for rigid pavement'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Higher CBR indicates stronger subgrade support, so the required flexible-pavement thickness generally decreases.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q114', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'medium', question: 'Using a fourth-power damage approximation relative to an 80 kN standard axle, the load equivalency factor for a 100 kN axle is closest to:', options: ['1.25', '2.44', '1.56', '3.05'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'LEF≈(100/80)^4=2.441.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q115', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'easy', question: 'A traffic signal has an 80 s cycle and a phase receives an effective green ratio of 0.45. Its effective green time is:', options: ['36 s', '28 s', '40 s', '44 s'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'g=0.45×80=36 s.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q116', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'medium', question: 'A lane has saturation flow 1800 veh/h of effective green and receives an effective green ratio 0.40. Its signalized capacity is:', options: ['450 veh/h', '1125 veh/h', '1800 veh/h', '720 veh/h'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Capacity=saturation flow×green ratio=1800×0.40=720 veh/h.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q117', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'hard', question: 'A transition curve is designed by limiting the rate of change of centrifugal acceleration to 0.5 m/s³. With speed 20 m/s and circular radius 400 m, using L=v³/(CR), the required length is:', options: ['20 m', '40 m', '80 m', '160 m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'L=20³/(0.5×400)=8000/200=40 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q118', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering — Traffic Shock Waves', difficulty: 'hard', question: 'Across a moving traffic boundary, the upstream state is q₁=1200 veh/h, k₁=20 veh/km and the downstream state is q₂=600 veh/h, k₂=60 veh/km. The shock-wave speed is:', options: ['+15 km/h', '−30 km/h', '+30 km/h', '−15 km/h'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Shock speed w=(q₂−q₁)/(k₂−k₁)=(600−1200)/(60−20)=−600/40=−15 km/h. The negative sign means the boundary moves upstream.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q119', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'easy', question: 'Traffic flow is 1800 veh/h and mean speed is 60 km/h. Using q=kv, traffic density is:', options: ['30 veh/km', '20 veh/km', '60 veh/km', '108 veh/km'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'k=q/v=1800/60=30 veh/km.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q120', section: 'Civil Engineering Paper II', topic: 'Transportation Engineering', difficulty: 'easy', question: 'Which design quantity combines driver perception-reaction distance and braking distance?', options: ['stopping sight distance', 'overtaking sight distance only', 'transition-curve length', 'traffic density'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Stopping sight distance is the distance needed for perception-reaction plus braking to a stop.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q121', section: 'Civil Engineering Paper II', topic: 'Surveying — Total-Station Coordinates', difficulty: 'medium', question: 'From station O with coordinates (100.000 m E, 200.000 m N), a point P lies 50.0 m horizontally on a bearing of 90° measured clockwise from north. The coordinates of P are:', options: ['(100.000 m E, 250.000 m N)', '(50.000 m E, 200.000 m N)', '(150.000 m E, 200.000 m N)', '(100.000 m E, 150.000 m N)'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'A 90° bearing points due east. The easting therefore increases by 50 m while northing is unchanged.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q122', section: 'Civil Engineering Paper II', topic: 'Surveying — Traverse Closure', difficulty: 'medium', question: 'For a closed traverse, the algebraic sum of latitudes is +0.12 m and the sum of departures is −0.16 m. The linear closing error is:', options: ['0.04 m', '0.14 m', '0.20 m', '0.28 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Linear closing error = √[(ΣL)²+(ΣD)²]=√(0.12²+0.16²)=√0.04=0.20 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q123', section: 'Civil Engineering Paper II', topic: 'Surveying — Magnetic Declination', difficulty: 'medium', question: 'A line has magnetic bearing 72°30′. At the site the magnetic declination is 2°15′ east. Its true bearing is:', options: ['70°15′', '72°30′', '74°15′', '74°45′'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For easterly declination, true bearing = magnetic bearing + declination =72°30′+2°15′=74°45′.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q124', section: 'Civil Engineering Paper II', topic: 'Surveying', difficulty: 'easy', question: 'In stadia tacheometry with horizontal sight, multiplying constant K=100, additive constant C=0 and staff intercept 1.20 m. Horizontal distance is:', options: ['12 m', '100 m', '144 m', '120 m'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'D=Ks+C=100×1.20=120 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q125', section: 'Civil Engineering Paper II', topic: 'Surveying', difficulty: 'hard', question: 'In reciprocal levelling across a river, setup near A gives readings A=1.20 m, B=2.00 m; setup near B gives A=0.80 m, B=1.50 m. The true RL difference (B−A) is:', options: ['−0.05 m', '−0.75 m', '+0.75 m', '+1.50 m'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Each observed difference is reading on A minus reading on B: −0.80 and −0.70 m. Their mean is −0.75 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q126', section: 'Civil Engineering Paper II', topic: 'Surveying', difficulty: 'easy', question: 'A closed rectangular traverse has coordinates (0,0), (4,0), (4,3), (0,3) m in order. Its area by coordinates is:', options: ['7 m²', '12 m²', '14 m²', '24 m²'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'The polygon is a 4 m × 3 m rectangle; the coordinate (shoelace) formula gives 12 m².', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q127', section: 'Civil Engineering Paper II', topic: 'Concrete Technology — Aggregate Moisture Correction', difficulty: 'medium', question: 'A concrete batch requires 800 kg of coarse aggregate in saturated-surface-dry condition. The stock aggregate contains 2% free surface moisture by SSD mass. What wet aggregate mass should be batched, and how much water does that free moisture contribute?', options: ['800 kg aggregate and 16 kg water', '816 kg aggregate and 8 kg water', '784 kg aggregate and 16 kg water', '816 kg aggregate and 16 kg water'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Free moisture =0.02×800=16 kg. Wet mass to supply 800 kg SSD solids is 800+16=816 kg, and the 16 kg free water must be credited against mixing water.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q128', section: 'Civil Engineering Paper II', topic: 'Concrete Technology', difficulty: 'hard', question: 'Using absolute volumes, estimate the yield of a batch containing 350 kg cement (SG 3.15), 180 kg water, 700 kg fine aggregate (SG 2.65) and 1200 kg coarse aggregate (SG 2.70).', options: ['about 0.70 m³', 'about 1.35 m³', 'about 2.43 m³', 'about 1.00 m³'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Absolute volumes are 350/(3.15×1000)+0.180+700/(2.65×1000)+1200/(2.70×1000)≈1.00 m³.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q129', section: 'Civil Engineering Paper II', topic: 'Concrete Technology', difficulty: 'medium', question: 'In the usual definition of characteristic compressive strength of concrete, approximately what fraction of valid test results may be expected to fall below fck?', options: ['1%', '5%', '10%', '50%'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Characteristic strength is conventionally the value below which not more than about 5% of results are expected to fall.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q130', section: 'Civil Engineering Paper II', topic: 'Concrete Technology', difficulty: 'medium', question: 'Using Ec=5000√fck (MPa), what elastic modulus corresponds to fck=25 MPa?', options: ['25,000 MPa', '5,000 MPa', '12,500 MPa', '125,000 MPa'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Ec=5000√25=25,000 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q131', section: 'Civil Engineering Paper II', topic: 'Concrete Technology', difficulty: 'easy', question: 'For fck=30 MPa and standard deviation s=5 MPa, a target mean strength based on fck+1.65s is:', options: ['31.65 MPa', '38.25 MPa', '35.00 MPa', '46.50 MPa'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: '30+1.65×5=38.25 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q132', section: 'Civil Engineering Paper II', topic: 'Concrete Technology', difficulty: 'easy', question: 'A mix contains 400 kg/m³ cement and is specified at w/c=0.45. Required mixing water is:', options: ['160 kg/m³', '180 kg/m³', '200 kg/m³', '222 kg/m³'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Water=0.45×400=180 kg/m³.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q133', section: 'Civil Engineering Paper II', topic: 'Steel Design', difficulty: 'medium', question: 'A steel section has plastic section modulus 600×10³ mm³ and fy=250 MPa. Ignoring factors, its plastic moment is:', options: ['60 kN·m', '240 kN·m', '150 kN·m', '375 kN·m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Mp=fyZp=250×600000=150×10^6 N·mm=150 kN·m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q134', section: 'Civil Engineering Paper II', topic: 'Steel Design', difficulty: 'easy', question: 'A compression member has effective length 3.0 m and radius of gyration 60 mm. Its slenderness ratio is:', options: ['20', '50', '60', '180'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'λ=Le/r=3000/60=50.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q135', section: 'Civil Engineering Paper II', topic: 'Steel Design', difficulty: 'medium', question: 'A 20 mm diameter bolt carries 50 kN in single shear. Using gross shank area, average shear stress is closest to:', options: ['80 MPa', '159 MPa', '250 MPa', '318 MPa'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'τ=P/A=50000/[π(20²)/4]=159 MPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q136', section: 'Civil Engineering Paper II', topic: 'Steel Design', difficulty: 'easy', question: 'For an 8 mm equal-leg fillet weld, using effective throat 0.7 times weld size, the throat is:', options: ['4.0 mm', '8.0 mm', '11.4 mm', '5.6 mm'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Effective throat=0.7s=0.7×8=5.6 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q137', section: 'Civil Engineering Paper II', topic: 'Steel Design — Fillet Weld Geometry', difficulty: 'medium', question: 'For an equal-leg fillet weld of nominal size 8 mm, taking effective throat thickness as 0.7 times the weld size, the effective throat is:', options: ['4.0 mm', '8.0 mm', '5.6 mm', '11.4 mm'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For a standard 45° equal-leg fillet, the effective throat is approximately 0.7s. Thus 0.7×8=5.6 mm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q138', section: 'Civil Engineering Paper II', topic: 'Steel Design', difficulty: 'medium', question: 'For bending about the same axis, a section has elastic modulus Ze and plastic modulus Zp=1.12Ze. Its shape factor is:', options: ['0.89', '1.00', '2.12', '1.12'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Shape factor is Mp/My=Zp/Ze=1.12 for the same yield stress.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q139', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'medium', question: 'Using qu=cNc+qNq and neglecting the Nγ term, with c=25 kPa, Nc=5.7, q=60 kPa and Nq=1.0, qu is:', options: ['202.5 kPa', '142.5 kPa', '167.5 kPa', '262.5 kPa'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'qu=25×5.7+60=202.5 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q140', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'hard', question: 'A 2.0 m wide footing carries vertical load 600 kN and moment 60 kN·m about its centroidal axis. The load eccentricity is 0.10 m. Which statement is correct?', options: ['the resultant lies outside the footing', 'the resultant lies within the middle third', 'soil tension is unavoidable because e>B/2', 'eccentricity has no effect on contact pressure'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For no tensile contact, e≤B/6=0.333 m. Here e=0.10 m, so the resultant lies within the middle third.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q141', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'easy', question: 'A square 2 m × 2 m footing carries a concentric service load of 800 kN. Ignoring footing self-weight, average contact pressure is:', options: ['100 kPa', '400 kPa', '200 kPa', '800 kPa'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'q=P/A=800/(2×2)=200 kPa.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q142', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'medium', question: 'When estimating axial capacity of a pile group, which check is essential in addition to summing individual pile capacities?', options: ['only the pile-head bending moment', 'only the water-table elevation', 'only the concrete slump', 'capacity of the group acting as a block'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Pile groups can fail as a block; design therefore compares group/block capacity with the sum of individual capacities as appropriate.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q143', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'medium', question: 'If surrounding compressible soil settles more than a pile shaft, negative skin friction on the pile primarily:', options: ['creates uplift capacity', 'eliminates end bearing', 'adds downward drag and increases axial load', 'reduces structural load to zero'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Relative downward movement of soil against the pile develops downdrag, adding compressive force to the pile.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q144', section: 'Civil Engineering Paper II', topic: 'Foundation Engineering', difficulty: 'medium', question: 'A rectangular footing is 2 m wide. To avoid tensile contact pressure under a uniaxial eccentric vertical load, the eccentricity should not exceed:', options: ['0.167 m', '0.500 m', '0.333 m', '1.000 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'For full compression under linear bearing pressure, e≤B/6=2/6=0.333 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q145', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'medium', question: 'A pump delivers 0.050 m³/s against 24 m head at 75% overall efficiency. Required input power is closest to:', options: ['8.8 kW', '15.7 kW', '11.8 kW', '23.5 kW'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Pin=ρgQH/η=1000×9.81×0.05×24/0.75≈15.7 kW.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q146', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'hard', question: 'For a pump, use Ns=N√Q/H^(3/4). If N=1000 rpm, Q=0.05 m³/s and H=20 m, Ns is closest to:', options: ['11.2', '47.3', '105.7', '23.6'], correctIndex: 3, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Ns=1000√0.05/20^0.75≈23.6 in the stated metric form.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q147', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'easy', question: 'A turbine runs at 300 rpm under 25 m head. Its unit speed N/√H is:', options: ['12 rpm', '60 rpm', '75 rpm', '1500 rpm'], correctIndex: 1, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Nu=N/√H=300/5=60 rpm.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q148', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'medium', question: 'Water flows in a wide rectangular channel at depth 1.0 m and velocity 4.0 m/s. The Froude number is closest to:', options: ['0.41', '0.80', '1.28', '4.00'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Fr=V/√(gy)=4/√9.81≈1.28, so the flow is supercritical.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q149', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'hard', question: 'For discharge per unit width q=4.0 m²/s in a rectangular channel, critical depth yc=(q²/g)^(1/3) is closest to:', options: ['1.18 m', '0.64 m', '1.63 m', '2.00 m'], correctIndex: 0, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'yc=(16/9.81)^(1/3)≈1.18 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
  { id: 'b14-001-ce-q150', section: 'Civil Engineering Paper II', topic: 'Hydraulics', difficulty: 'hard', question: 'A rectangular channel has upstream depth 0.50 m and velocity 6.0 m/s before a hydraulic jump. Using the conjugate-depth relation, downstream depth is closest to:', options: ['0.74 m', '1.00 m', '1.68 m', '3.36 m'], correctIndex: 2, answerType: 'mcq', marks: 2, negativeMarking: 0.6666666666666666, explanation: 'Fr1=6/√(9.81×0.5)≈2.71 and y2/y1=[√(1+8Fr1²)−1]/2≈3.36, giving y2≈1.68 m.', source: { kind: 'original', reference: 'UPSC Engineering Services Examination 2026 Notice', url: 'https://www.upsc.gov.in/sites/default/files/Notif-ESEP-26-Engl.pdf', checkedOn: '2026-09-10' } },
];
